{{-- Membership New navigation colour standard - 24 Sep 2026 --}}
<style>
/*
 * System-standard coloured navigation buttons.
 * Inactive buttons: colour background + white text.
 * Active page: white background + black text, retaining the button colour as border/accent.
 */
.mn-nav > a{
    --mn-nav-color:#2563eb;
    background:var(--mn-nav-color)!important;
    border-color:var(--mn-nav-color)!important;
    color:#fff!important;
    box-shadow:0 6px 14px color-mix(in srgb, var(--mn-nav-color) 22%, transparent)!important;
}
.mn-nav > a:nth-child(1){--mn-nav-color:#2563eb} /* blue */
.mn-nav > a:nth-child(2){--mn-nav-color:#16a34a} /* green */
.mn-nav > a:nth-child(3){--mn-nav-color:#7c3aed} /* purple */
.mn-nav > a:nth-child(4){--mn-nav-color:#0891b2} /* cyan */
.mn-nav > a:nth-child(5){--mn-nav-color:#f59e0b} /* amber */
.mn-nav > a:nth-child(6){--mn-nav-color:#4f46e5} /* indigo */
.mn-nav > a:nth-child(7){--mn-nav-color:#e11d48} /* rose */
.mn-nav > a:nth-child(8){--mn-nav-color:#0f766e} /* teal */
.mn-nav > a:nth-child(9){--mn-nav-color:#475569} /* slate */
.mn-nav > a:nth-child(10){--mn-nav-color:#c2410c} /* orange */
.mn-nav > a:nth-child(11){--mn-nav-color:#9333ea} /* violet */
.mn-nav > a:nth-child(12){--mn-nav-color:#0369a1} /* sky */
.mn-nav > a:hover{
    background:var(--mn-nav-color)!important;
    border-color:var(--mn-nav-color)!important;
    color:#fff!important;
    filter:brightness(.92);
    transform:translateY(-1px);
}
.mn-nav > a.active,
.mn-nav > a.active:hover{
    background:#fff!important;
    border-color:var(--mn-nav-color)!important;
    color:#0f172a!important;
    box-shadow:inset 0 0 0 1px color-mix(in srgb, var(--mn-nav-color) 20%, transparent),0 5px 14px color-mix(in srgb, var(--mn-nav-color) 18%, transparent)!important;
    filter:none;
    transform:none;
}
/* Fallback for browsers without color-mix support. */
@supports not (color:color-mix(in srgb, red, blue)){
    .mn-nav > a{box-shadow:0 6px 14px rgba(15,23,42,.12)!important}
    .mn-nav > a.active,.mn-nav > a.active:hover{box-shadow:0 5px 14px rgba(15,23,42,.10)!important}
}
</style>

